use anyhow::{Result,anyhow};use image::RgbaImage;
use std::{sync::{Arc,Mutex,Condvar,mpsc::{self,Receiver,SyncSender}},thread,time::Instant};
use crate::{hud::{Hud,Content},gpu::Gpu};
#[derive(Clone,Copy,Debug)]pub struct Rect{pub left:u32,pub top:u32,pub right:u32,pub bottom:u32}
#[derive(Default,Clone,Copy)]pub struct HudCost{pub render:f64,pub pack:f64,pub transfer:f64,pub mip:f64,pub total:f64,pub worker_render:f64,pub worker_pack:f64,pub worker_diff:f64,pub bytes:u64,pub updated:bool}
fn ms(t:Instant)->f64{t.elapsed().as_secs_f64()*1000.0}
fn key(c:&Content)->u64{use std::hash::{Hash,Hasher};let mut hash=std::collections::hash_map::DefaultHasher::new();key_base(c).hash(&mut hash);c.combat.hash(&mut hash);hash.finish()}
fn key_base(c:&Content)->[i32;28]{let mut k=[0;28];k[0]=c.scores[0]as i32;k[1]=c.scores[1]as i32;k[2]=(c.tick/60.0)as i32;for i in 0..10{let hp=c.health[i/5][i%5];k[3+i]=(hp.clamp(0.0,1.0)*64.0).round()as i32;k[13+i]=(hp>0.0)as i32;}k[23]=c.show_intro as i32;if let Some((s,h,d,y))=c.adjustment{k[24]=(s*100.0).round()as i32;k[25]=(h*100.0).round()as i32;k[26]=(d*100.0).round()as i32;k[27]=y.round()as i32;}else{k[24]=i32::MIN;}k}
pub fn dirty_rects(previous:&[u8],pixels:&[u8],width:u32,height:u32)->Vec<Rect>{if previous.len()!=pixels.len(){return vec![Rect{left:0,top:0,right:width,bottom:height}];}let mut result=Vec::with_capacity(24);let stride=width as usize*4;for top in (0..height).step_by(32){let bottom=(top+32).min(height);let span=top as usize*stride..bottom as usize*stride;if previous[span.clone()]==pixels[span]{continue;}let(mut left,mut right)=(width,0);for y in top..bottom{let row=y as usize*stride;for x in 0..width{let p=row+x as usize*4;if previous[p..p+4]!=pixels[p..p+4]{left=left.min(x);right=right.max(x+1);}}}if right>left{result.push(Rect{left,top,right,bottom});}}result}
struct Frame{pixels:Vec<u8>,rects:Vec<Rect>,render:f64,pack:f64,diff:f64}
struct Request{content:Option<Content>,stop:bool}
struct Worker{request:Arc<(Mutex<Request>,Condvar)>,frames:Option<Receiver<Result<Frame,String>>>,recycle:SyncSender<Vec<u8>>,thread:Option<thread::JoinHandle<()>>}
impl Worker{
 fn new(portraits:&[Vec<RgbaImage>;2])->Result<Self>{let portraits=portraits.clone();let request=Arc::new((Mutex::new(Request{content:None,stop:false}),Condvar::new()));let shared=request.clone();let(tx,rx)=mpsc::sync_channel(1);let(recycle,free)=mpsc::sync_channel::<Vec<u8>>(2);let handle=thread::Builder::new().name("HUD 준비".into()).spawn(move||{
  let run=||->Result<()>{let mut hud=Hud::new(&portraits)?;let(width,height)=(hud.width,hud.height);let mut previous=Vec::new();loop{let content={let(lock,signal)=&*shared;let mut r=lock.lock().unwrap();while r.content.is_none()&&!r.stop{r=signal.wait(r).unwrap();}if r.stop{break;}r.content.take().unwrap()};if let Ok(pixels)=free.try_recv(){hud.replace_pixels(pixels);}else{hud.replace_pixels(Vec::new());}let t=Instant::now();hud.render(&content);let render=ms(t);let mut pixels=hud.take_pixels();let t=Instant::now();for p in pixels.chunks_exact_mut(4){if p[3]==0{p.fill(0);}}let pack=ms(t);let t=Instant::now();let rects=dirty_rects(&previous,&pixels,width,height);previous.resize(pixels.len(),0);previous.copy_from_slice(&pixels);let diff=ms(t);if tx.send(Ok(Frame{pixels,rects,render,pack,diff})).is_err(){break;}}Ok(())};if let Err(e)=run(){let _=tx.send(Err(format!("HUD 준비 스레드: {e:#}")));}})?;Ok(Self{request,frames:Some(rx),recycle,thread:Some(handle)})}
 fn request(&self,c:Content){let(lock,signal)=&*self.request;lock.lock().unwrap().content=Some(c);signal.notify_one();}
 fn poll(&self)->Result<Option<Frame>>{match self.frames.as_ref().unwrap().try_recv(){Ok(Ok(frame))=>Ok(Some(frame)),Ok(Err(e))=>Err(anyhow!(e)),Err(mpsc::TryRecvError::Empty)=>Ok(None),Err(mpsc::TryRecvError::Disconnected)=>Err(anyhow!("HUD 준비 스레드 연결 종료"))}}
}
impl Drop for Worker{fn drop(&mut self){let(lock,signal)=&*self.request;if let Ok(mut r)=lock.lock(){r.stop=true;r.content=None;}signal.notify_one();self.frames.take();if let Some(t)=self.thread.take(){let _=t.join();}}}
enum Mode{Sync(Hud),Async(Worker)}
pub struct HudStream{mode:Mode,last_key:Option<u64>,ready:bool}
impl HudStream{
 pub fn new(portraits:&[Vec<RgbaImage>;2],synchronous:bool)->Result<Self>{Ok(Self{mode:if synchronous{Mode::Sync(Hud::new(portraits)?)}else{Mode::Async(Worker::new(portraits)?)},last_key:None,ready:false})}
 pub fn ready(&self)->bool{self.ready}
 pub fn update(&mut self,gpu:&Gpu,content:Option<Content>)->Result<HudCost>{let t=Instant::now();let mut cost=HudCost::default();match &mut self.mode{Mode::Sync(hud)=>{if let Some(c)=content{let start=Instant::now();let pixels=hud.render(&c);cost.render=ms(start);gpu.update_hud(pixels)?;let times=gpu.hud_times.get();cost.pack=times[0];cost.transfer=times[1];cost.mip=times[2];cost.bytes=pixels.len()as u64;cost.updated=true;self.ready=true;}},Mode::Async(worker)=>{if let Some(c)=content{let k=key(&c);if self.last_key!=Some(k){self.last_key=Some(k);worker.request(c);}}if let Some(frame)=worker.poll()?{gpu.update_hud_regions(&frame.pixels,&frame.rects)?;let times=gpu.hud_times.get();cost.transfer=times[1];cost.mip=times[2];cost.worker_render=frame.render;cost.worker_pack=frame.pack;cost.worker_diff=frame.diff;cost.bytes=frame.rects.iter().map(|r|(r.right-r.left)as u64*(r.bottom-r.top)as u64*4).sum();cost.updated=!frame.rects.is_empty();self.ready=true;let _=worker.recycle.try_send(frame.pixels);}}}cost.total=ms(t);Ok(cost)}
}
#[cfg(test)]mod tests{use super::*;#[test]fn dirty_regions_reconstruct_full_frame(){let(w,h)=(64,96);let old=vec![0;w*h*4];let mut new=old.clone();new[(37*w+12)*4..(37*w+12)*4+4].copy_from_slice(&[40,20,10,255]);let rects=dirty_rects(&old,&new,w as u32,h as u32);assert_eq!(rects.len(),1);assert_eq!(rects[0].left,12);assert_eq!(rects[0].right,13);let mut reconstructed=old;for r in rects{for y in r.top..r.bottom{let a=(y as usize*w+r.left as usize)*4;let b=(y as usize*w+r.right as usize)*4;reconstructed[a..b].copy_from_slice(&new[a..b]);}}assert_eq!(reconstructed,new);assert!(dirty_rects(&new,&new,w as u32,h as u32).is_empty());}
#[test]fn combat_changes_invalidate_hud_key(){let a=Content{combat:Default::default(),scores:[0,0],tick:60.0,health:[[1.0;5];2],show_intro:false,adjustment:None};let mut b=a;b.combat.available=true;assert_ne!(key(&a),key(&b));let c=b;b.combat.players[0][0].respawn=2;assert_ne!(key(&b),key(&c));b=c;b.combat.feed[0].tick=1805;assert_ne!(key(&b),key(&c));b=c;b.combat.flags=4;assert_ne!(key(&b),key(&c));}
#[test]fn hud_key_tracks_visible_values(){let a=Content{combat:Default::default(),scores:[1,2],tick:120.0,health:[[1.0;5];2],show_intro:false,adjustment:None};let mut b=a;b.tick=129.0;assert_eq!(key(&a),key(&b));b.tick=180.0;assert_ne!(key(&a),key(&b));b=a;b.health[0][0]=0.0;assert_ne!(key(&a),key(&b));b=a;b.adjustment=Some((1.0,0.76,1.4,0.0));assert_ne!(key(&a),key(&b));}}
